quests[64863] = { id = 64863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Guardians", description = "Those constructs patrolling the creche are not animated by the Earth-Warder's magic.\n\n<Dervishian narrows her eyes.>\n\nWe cannot allow there to be enemies in our midst.\n\nDestroy them to clear our path forward.", progress = "Who would dare defy the Earth-Warder in this way?", completion = "Those constructs were animated with blue dragonflight magic. \n\nThe Earth-Warder would never have allowed this!", objectives = "Defeat 4 Guardians or Constructs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64864] = { id = 64864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Awaken, Dracthyr", description = "<Only flashes of memory remain as you shake off what feels like an endless sleep.\n\nThe dracthyr before you is unresponsive, frozen in place by some unknown magic. You sense that within you lies the power to break your ally free.\n\nThere may be others within the creche who are suspended in this stasis.\n\nIt is your duty to awaken them.>", completion = "<Azurathel listens to your report.>\n\nMy memories are as broken as yours, {name}. But we cannot dwell on that now.\n\nWe need to assess and make a plan.", objectives = "Awaken the other dracthyr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64865] = { id = 64865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gear Up", description = "Hostiles have invaded, our people have been confined in magical stasis, and our creche seems to be collapsing.\n\nThis is why we train, {name}. When in doubt, fall back to what you know.\n\nFirst things first. Weapons, armor, supplies. Gather what you can find and get equipped while I marshal our forces.\n\nThen we will locate the Earth-Warder. Surely Neltharion can provide the answers we seek.", progress = "When memory fails, fall back on your training.", completion = "This gear is ancient, and the food has turned to dust.\n\nIt makes no sense... those rations should have lasted a lifetime.\n\nWell, we will make do with what we have.", objectives = "Acquire weapons, armor, and supplies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64866] = { id = 64866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Cauldron", description = "Your skills are needed, evoker.\n\nThe creche is crumbling and we have few supplies. We must reach the passage out, but we have to get past this arcane barrier first.\n\nIn the chamber beyond, there are dracthyr in need of aid. Tend their wounds. Destroy any foe who stands in your way.\n\nThis may be the last time we walk these halls together, {name}. Make it count.", completion = "You healed our people. Well done.\n\nNow to deal with that dragon.", objectives = "Prepare to leave the creche.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64867] = { id = 64867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies from The Enlightened", description = "Ah, yes. How I've looked forward to this moment for quite some time!\n\nCome, visit me. Let us share this achievement together.\n\nI've prepared something special just for you.", completion = "Quite a hefty reward. Are you sure you can manage all on your own?", objectives = "Speak with Vilo at Haven in Zereth Mortis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64870] = { id = 64870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon of Enlightened Brokers", description = "My, my. You've been busy, haven't you?", completion = "Let's see if we can find a suitable reward for your efforts.", objectives = "Speak with Vilo at Haven in Zereth Mortis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64871] = { id = 64871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dragon at the Door", completion = "We will get that rubble cleared and make sure no {race} is left behind.\n\nBut first, we need to secure this area.", objectives = "Defeat Lapisagos and escape the War Creche.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64872] = { id = 64872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fire Within", description = "You are an evoker, {name}. The best of the best. An elite soldier who has mastered the skills of each of our weyrns.\n\nI expect a lot of you.\n\nYour memories may be broken, but the might of dragons courses through your veins. Harness it.\n\nOne of your most potent weapons is your breath attack. The fire within becomes more powerful the longer you inhale.\n\nThese insects swarming over our training grounds should make fine targets.", progress = "A nice, deep breath clears the head.", completion = "Good. You remember your training.\n\nKeep your head low and your lungs full.", objectives = "Learn Fire Breath and practice empowered attacks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64873] = { id = 64873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stretch Your Wings", description = "I am heartened to see that so many escaped the War Creche. My own weyrn... was not as fortunate.\n\n<Emberthal stands in silence for a moment.>\n\nThere are other creches throughout the Reach, filled with dracthyr in peril. Strong wings will be needed to reach them.\n\nFocus. Remember your training. Get a feel for the wind again. You must regain your strength and fly to the other creches.\n\nThe time for rest is over.", completion = "You are getting the hang of this a lot faster than I was!\n\nBut then, you finished your {class} training. I was hoping to specialize as a diplomat.", objectives = "Practice casting Soar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64875] = { id = 64875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Wonderful", description = "{name}, I am so glad you are here! Firim sent me to find you.\n\nIt's the oracle, it... well... it's hard to describe. You should come see it for yourself. Hurry!", progress = "We must hurry, {name}. We do not know how long this will last.", completion = "We may be on the cusp of a wondrous revelation!", objectives = "Travel to Exile's Hollow to witness for yourself what is happening to Saezurah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64876] = { id = 64876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Music of the Spheres", description = "It started gradually, the energy emanating from the oracle in increasing amounts, until the grand design you see before you took shape.\n\nThe terrible clamor ringing in our ears began shortly afterward.\n\nMy attempts to approach the fractals have been... unsuccessful. But they appear to resonate with Pocopoc.\n\nYou share a special bond with it; perhaps you shall have better luck than I.", completion = "A vision! The oracle communicates with us! You saw it too? Such magnificence! Such... a migraine left in its wake.", objectives = "Examine the fractals that surround Saezurah's body.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64877] = { id = 64877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Navigation Playtest: Level Up (PART 2)", description = "Enjoy the end of Lowlands!" }
quests[64878] = { id = 64878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What a Long Strange Trip", description = "<The voice from the vision speaks through Pocopoc, albeit distant and distorted.>\n\nI... am Saezurah. Oracle. This automa... speaks with my voice. Acts with my will. For now.\n\nThe pattern... is torn. Disrupted. Mending must be done.\n\nA great hunger swarms the sands. What it seeks must not be consumed.\n\nJourney with me. Follow my voice.", progress = "Pocopoc has not reached the destination yet.", completion = "Above the sands. Above us. The vessel awaits.", objectives = "Go with Pocopoc to make sense of your vision.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64879] = { id = 64879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Monumental Discovery", description = "Maw Walker--Pelagos stopped by earlier to give a report and said that the oracle's preparations were complete, and you were urgently needed. \n\nIf this is something that can help our efforts, I want you involved. Head to Exile's Hollow and see what they need.", completion = "Mortal, I have monumental news. Saezurah has indicated that preparations are complete. It is time to create a new Arbiter!", objectives = "Meet Firim in Exile's Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64888] = { id = 64888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Borrowed Power", description = "The land provides. The land thirsts. Invaders devour what we require.\n\nReclaim what has been consumed. Absorb what remains abundant.\n\nWings need wind to fly. We need power to ascend.", progress = "More power to Pocopoc.", completion = "Power thrums. A renewal of hope.", objectives = "Defeat volatile lured enemies or soak power from pools to reclaim Cosmic Energy to empower Pocopoc.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64889] = { id = 64889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Match Made in Zereth Mortis", description = "The cyphers are the key. Each one, a step along the path. You must find them all.\n\nEnter the inner chamber. The Prime Locus Arrangement awaits.\n\nThe first step toward ascension. Toward the vessel.", progress = "Need to gather the cyphers to reach the door where the vessel waits.", completion = "The last leg of the journey begins.", objectives = "Study the Locus Arrangements and use the Locus Shift to reach the Ultimus Locus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64935] = { id = 64935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Between a Rock & a Rock", description = "<Piles of rock are scattered around the area. The devourers have done enough damage to obscure the cypher you seek.\n\nPerhaps one of the nearby servitors could be made to clear the rubble.>", progress = "Until we discover the cypher, we need to keep smashing rubble.", completion = "Our sojourn continues.", objectives = "Smash the rubble barring access to the secundus locus arrangement.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64936] = { id = 64936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Searching High and Low", description = "Three locks upon the door, three keys hidden atop the zenith.\n\nFind the phrases. Speak the words. Secure the vessel.", progress = "The vessel slumbers high above.", completion = "One journey ends. Another begins.", objectives = "Gather the Ingress Phrases on the Ultimus Locus that are needed to claim the Vessel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64937] = { id = 64937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Light Up My Life", description = "Great power entices great hunger. The insatiable devourers scale the cliffs in search of sustenance.\n\nSoon they will swarm the plateau. They seek to consume all they encounter. The vessel. Its power. Us.\n\nThis must not come to pass. Wield this automa. Silence their slavering howls.", completion = "Sanctuary, for now. A greater task remains.", objectives = "Use Pocopoc to defend the vessel against the devourers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64941] = { id = 64941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chicken Soul", description = "<The Chicken Soul is perky and voracious. The shape of the chicken will be yours to call upon.>", completion = "Ooh, a chicken! You can cluck like one now, too!", objectives = "Bring the Chicken Soul to Choofa in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64942] = { id = 64942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Primus", description = "Though we fought to stop the Jailer in the Sanctum of Domination, we failed. He enveloped Oribos in the Maw, struck down the Arbiter, and opened the way to Zereth Mortis. \n\nThe time has come to follow him. \n\nWithin the Arbiter's Chamber, we will forge our own path.\n\nHurry, Maw Walker. The fate of the Shadowlands, and all the realms beyond, is at stake.", completion = "There is but one final sigil needed to pursue Zovaal.", objectives = "Speak with Tal-Inara in Oribos to travel to the Arbiter's Chamber.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64944] = { id = 64944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hasty Voyage", description = "The path to Zereth Mortis is open.\n\nWe must part ways here. The Eternal Ones are forbidden from returning to the place of our creation. Zovaal has defied the most sacred laws of the Progenitors.\n\nYou must undertake this journey alone.\n\nGo. Find a foothold in Zereth Mortis so that we can send the covenant forces through.\n\nThen we will pursue the Jailer and end his madness.", completion = "This... certainly is not Oribos.", objectives = "Begin your journey to Zereth Mortis by mounting the anima wyrm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64945] = { id = 64945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strangers in a Strange Land", description = "Did we... did we reach Zereth Mortis? And are we walking on water?\n\nWhat a wondrous place! At least, from what I can tell through this fog.\n\nI think I can make out a structure in the distance. Perhaps we will find answers there.", completion = "I will not abide agents of the Jailer defiling this land!", objectives = "Accompany Pelagos and explore your surroundings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64947] = { id = 64947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Give Me A Hand", description = "To drive the Jailer from Zereth Mortis, we must direct all our resources against the enemy.\n\nAn object of potential power lies in a nearby repository, but the chamber's defenses respond only to automa. I would never harm their kind, but I have encountered one that no longer functions.\n\nIf you extract its hand, we could use the inert appendage to gain access to the repository.\n\nI find such use of the First Ones' creations unsavory, but we cannot abide the presence of Mawsworn in this realm.", completion = "Admittedly, I did not foresee this result.", objectives = "Assist Firim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64949] = { id = 64949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Research Purposes", description = "I have taken pains not to disturb the automa during my time in Zereth Mortis, and so far they have paid little attention to me.\n\nIt seems recent events have changed that.\n\nAgain, let me be clear that I have no wish to harm the creations of the First Ones. But if, in the course of your efforts, conflict with the automa becomes inevitable, we must ensure that some good can come of it.\n\nIf I can examine fragments of fallen automa, it may provide knowledge to use against the Mawsworn.\n\nGo carefully.", progress = "Did you find any useful fragments?", completion = "Though the loss of automa is unfortunate, these fragments could prove a boon to my research.", objectives = "Collect 12 Intact Automa Fragments from Alerted Automa within Genesis Vestibule", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64950] = { id = 64950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mutual Exchange", description = "It seems the other automa did not appreciate our appropriation of their colleague's hand. They have become hostile.\n\nUnfortunate, but we cannot allow this to impede our progress.\n\nThe automa's hand should activate a console within the Genesis Repository. I believe it holds an object of great potential.\n\nAfter you acquire it, I will guide you to a place that may provide a means to reach the allies you left behind.\n\nDo we have an accord?", progress = "Did you acquire the object from the console?", completion = "<Firim snatches the core from your hands.>\n\nIntriguing. I have examined many automa cores, but this one glows with an energy unlike any I have seen before.", objectives = "Use the Automa Hand to activate an Automa Console and obtain the Repository Treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64951] = { id = 64951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Road to Haven", description = "I did not expect to encounter a living mortal and a kyrian this day, but your assistance has been valuable.\n\nBefore I begin my studies of this automa core, I will guide you to Haven, the settlement founded by my expedition upon our arrival.\n\nThough my colleagues saw fit to exile me for challenging their \"Enlightened\" dogma, I have no wish to see Haven wiped from existence by the Jailer.\n\nAid them and they may assist your efforts to return to your allies. We brokers are nothing if not transactional.", completion = "I can go no further.\n\nMy former colleagues and I have... philosophical differences.", objectives = "Ride with Firim out of the Genesis Repository.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64952] = { id = 64952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroying the Destructors", description = "The Mawsworn possess terrible weapons that gather dark magic and hurl it against our gates.\n\nThe defensive barrier around Haven will not hold much longer. All that we are, all that we hold dear, will soon be erased from existence.\n\nIf you are who you claim to be, then prove it to us. Destroy the enemy's armaments and help defend our home.\n\nI pray to the First Ones that you succeed.", completion = "You have bought us time, mortal. First Ones bless us all.", objectives = "Destroy 4 Maw Destructors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64953] = { id = 64953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defending Haven", description = "The Mawsworn are gathering in force outside our very gates. It is clear they mean to overrun our home!\n\nThe Enlightened wish only to honor the marvels of the First Ones in peace. Haven's defensive barrier was put in place to shield us from minor threats. We did not imagine the Jailer would send his forces against us.\n\nYou claim to be our ally, mortal? Then help us defend this sacred land.", progress = "Our pilgrims cannot continue like this.", completion = "You have proven your mettle, yet the enemy grows bolder.", objectives = "Defeat 13 Mawsworn in the Great Veldt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64957] = { id = 64957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Old Waystone", description = "The Jailer has withdrawn his forces. I should be relieved, but I fear this means he has found a way into the Sepulcher.\n\n<Elder Ara trembles.>\n\nDespite Elder Kreth's doubts, you have proven to be an ally. Something we need more of.\n\nWhen our expedition arrived in Zereth Mortis, we discovered a dormant waystone. If you are indeed a Maw Walker, then the prophecies tell us that you will be able to activate it.\n\nIf your allies can save this sacred place, then the path to them must be opened.\n\nCome.", completion = "Maw Walker! Thank the Light you and Pelagos are safe!", objectives = "Open the Waystone to Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64958] = { id = 64958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forces Gather", completion = "You defended Haven, and now you bring allies to preserve this sacred land.\n\nBlessings of the First Ones be upon you, mortal.", objectives = "Speak to Elder Kreth in Zereth Mortis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64959] = { id = 64959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Otter Soul", description = "<The Otter Soul is swift and boastful. The shape of the otter will be yours to call upon.>", completion = "Ooh, an otter! You can float like one now, too!", objectives = "Bring the Otter Soul to Choofa in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64960] = { id = 64960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feed the Annelids" }
quests[64961] = { id = 64961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cat Soul", description = "<The Cat Soul is elegant and inquisitive. The shape of the cat will be yours to call upon.>", completion = "Ooh, a cat! You can pounce like one now, too!", objectives = "Bring the Cat Soul to Choofa in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64962] = { id = 64962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "As Foretold", description = "The spheres are in place. A melody builds. Go--bring forth the chorus of Scryers, that the cycle of rebirth may begin.", progress = "The song awaits its chorus.", completion = "The rustle of creation, whisper in the dark. We may begin.", objectives = "Bring Firim and the Scryers to the center.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64963] = { id = 64963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Defector's Request", description = "<Unrolling the scroll, you can make out that it's a coded arms requisition from the Maldraxxi of Death's End to their venthyr allies... all servants of the Jailer.\n\nSurely someone among the Death's Advance in Korthia will be able to help you fully break the code and learn exactly what they were planning.>", completion = "<A smile creeps across Duchess Mynx's face as she looks over the scroll you provided. A moment later, an echoing laugh bursts from her.>\n\nThe forces of the Jailer use such pathetic codes! This scroll of yours doesn't say where, but it seems there's a weapons cache ready to be claimed. A team of your allies should be able to investigate and retrieve it without too much trouble.", objectives = "Deliver the missive to Duchess Mynx in Keeper's Respite in Korthia.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64964] = { id = 64964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Choose Your Fighter", description = "The presence of the Jailer's forces at Provis Strata have been causing untold damage to the region. If left unchecked, we will lose all knowledge in the area.\n\nOne of our kin has prepared some automa to deal with the Mawsworn. Meet with them, and fight back against those who would disrespect Zereth Mortis in this manner.", progress = "Is the task complete?", completion = "Good work.", objectives = "Pick an automa construct and use it against the Mawsworn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64969] = { id = 64969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Weeds", description = "I understand now why Elder Nirav is filled with worry.\n\nMany of the pilgrims who have journeyed to the Catalyst Wards have not returned. This includes Feroz, who is most likely to have information we need to restore the remnants. \n\nPrepare yourself. The First Ones's newest creations are prevalent at the Catalyst. If something has gone wrong there, it could be tragically dangerous.", completion = "Feroz explained what happened to the missing pilgrims.\n\nThey are trapped inside the Catalyst Wards!", objectives = "Meet Elder Ara outside the Catalyst Wards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64970] = { id = 64970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timeworn Keystone: The Broken Isles", description = "I recently came into possession of a unique keystone. It may look old and worn, but I believe it still has a story to tell.\n\nTake it with you. Perhaps it will serve as a reminder of adventures long past. Adventures I hope you will tell me about, of course.", completion = "Your tales of adventure are most exciting, my friend! Please, allow me to offer a token of my gratitude.", objectives = "Complete a Timeworn Keystone dungeon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64974] = { id = 64974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clean Up, Automa Aisle" }
quests[64977] = { id = 64977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Step Into the Ring", description = "One of the remarkable things we have found about these lands is that they seem to be adaptive and changing, even as ancient as they are. Things are not stationary.\n\nIn the depths of the Nexus of Actualization there is a forge that appears made to test these various designs, and to learn. These creatures may one day be used to defend Zereth Mortis from threats, so you should test their effectiveness where possible.\n\nGo there, challenge what the forge creates and report back to me.", completion = "What a remarkable device. Of course there is clearly some improvement to be made in what it creates. But perhaps it will learn from the lessons you have provided.", objectives = "Defeat Generated creations in the Nexus of Actualization.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64984] = { id = 64984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bunny Soul", description = "<The Bunny Soul is clever and quick. The shape of the bunny will be yours to call upon.>", completion = "Ooh, a bunny! You can hop like one now, too!", objectives = "Bring the Bunny Soul to Choofa in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64985] = { id = 64985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rat Soul", description = "<The Rat Soul is curious and sociable. The shape of the rat will be yours to call upon.>", completion = "Ooh, a rat! They're so clever!", objectives = "Bring the Rat Soul to Choofa in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
