quests[64989] = { id = 64989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Porcupine Soul", description = "<The Porcupine Soul is cautious and shy. The shape of the porcupine will be yours to call upon.>", completion = "Ooh, a porcupine! Some say they're prickly, but I think they're nice.", objectives = "Bring the Porcupine Soul to Choofa in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
