quests[64992] = { id = 64992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prairie Dog Soul", description = "<The Prairie Dog Soul is ever alert. The shape of the prairie dog will be yours to call upon.>", completion = "Ooh, a prairie dog! Nothing will get past you!", objectives = "Bring the Prairie Dog Soul to Choofa in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64993] = { id = 64993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saurolisk Hatchling Soul", description = "<The Saurolisk Hatchling Soul is tenacious and fierce. The shape of the saurolisk hatchling will be yours to call upon.>", completion = "Ooh, a saurolisk hatchling! So cute, but so fierce!", objectives = "Bring the Saurolisk Hatchling Soull to Choofa in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
