quests[64995] = { id = 64995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saurid Soul", description = "<The Saurid Soul is a mischievous and playful one. The shape of the saurid will be yours to call upon.>", completion = "Ooh, a saurid! Lady Moonberry had a prank war with a big one of those, once. Hek hek hek!", objectives = "Bring the Saurid Soul to Choofa in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
