quests[65008] = { id = 65008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goat Soul", description = "<The Goat Soul is stoic and unwavering. The shape of the goat will be yours to call upon.>", completion = "Ah, the goat. This shape is now yours to call upon.", objectives = "Bring the Goat Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
