quests[65335] = { id = 65335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News from Oribos", description = "I bear important news that will grant us insight into the Jailer's methods. \n\nWith faith and understanding, we may also execute true justice.\n\nThere is much we should discuss, Hero.", progress = "In transformation, there can be redemption.", completion = "Sylvanas's experience may be intrinsic to Anduin's fate.", objectives = "Speak to Uther the Lightbringer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65336] = { id = 65336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schematic Reassimilation: Stabilized Geomental", description = "<This schematic contains the pattern of a new protoform construct. Present it to an appropriate protoform forge and it may instantiate one of these creatures for you.>", completion = "<The protoform forge chimes a melancholy song as it draws in the schematic.>", objectives = "Present the schematic to an appropriate protoform forge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65348] = { id = 65348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schematic Reassimilation: Omnipotential Core", description = "<This schematic contains the pattern of a new protoform construct. Present it to an appropriate protoform forge and it may instantiate one of these creatures for you.>", completion = "<The protoform forge chimes a melancholy song as it draws in the schematic.>", objectives = "Present the schematic to an appropriate protoform forge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65349] = { id = 65349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Grace", description = "The waters of the Wellspring no longer flow.\n\nThe designs of the First Ones have never before failed us. The pilgrims are beginning to wonder... are the First Ones displeased?\n\nCertainly they may question, but MY faith remains steadfast. And as I expected, it seems the First Ones have sent us a solution. \n\nYou, of course. \n\nAncient research and texts indicate that the source of the wellspring is in an underground temple in Provis Esper. Go, I have faith that you will restore the Wellspring.", completion = "<This automa has been ravaged by devourers. It clutches a curious object in its hand.>", objectives = "Travel to Provis Esper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65350] = { id = 65350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restore the Flow", description = "Look! Devourers have penetrated the temple's defenses. Those ravenous menaces feed on any energy that they can find. They must have been drawn to the wellspring's power.\n\nWith that kind of interference, no wonder the waters have been stalled!\n\nThe solution must be inside Locrian Esper. Once there, see if you can find a way to reverse the damage that has been done.", progress = "<The console thrums with power.>", completion = "<It seems as though your efforts were successful--the waters are once again flowing through the temple. The wellspring should be restored.>", objectives = "Find a way to restore Locrian Esper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65351] = { id = 65351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schematic Reassimilation: Resonant Echo", description = "<This schematic contains the pattern of a new protoform construct. Present it to an appropriate protoform forge and it may instantiate one of these creatures for you.>", completion = "<The protoform forge chimes a melancholy song as it draws in the schematic.>", objectives = "Present the schematic to an appropriate protoform forge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65353] = { id = 65353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Automa-free Diet", description = "These devourers are relentless! They feed on any energy they can find. If left unchecked, they would surely devour the whole of Zereth Mortis. We cannot allow the creations of the First Ones to be sullied by these invaders! \n\nI am no fighter. But you... perhaps the First Ones delivered you to us after all. Will you help?", completion = "Stranger, I... I apologize. My trust in you was lacking. In turn, my faith wavered as well. Forgive me, and take with you my thanks--the First Ones truly guide your hand.", objectives = "Kill 10 Invading Gorgers and Reality Breachers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65354] = { id = 65354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schematic Reassimilation: Prototickles", description = "<This schematic contains the pattern of a new protoform construct. Present it to an appropriate protoform forge and it may instantiate one of these creatures for you.>", completion = "<The protoform forge chimes a melancholy song as it draws in the schematic.>", objectives = "Present the schematic to an appropriate protoform forge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
